def query_by_short_id(context, model, short_id, project_safe=True):
    q = model_query(context, model)
    q = q.filter(model.id.like('%s%%' % short_id))

    if project_safe:
        q = q.filter_by(project=context.project)

    if q.count() == 1:
        return q.first()
    elif q.count() == 0:
        return None
    else:
        raise exception.MultipleChoices(arg=short_id)

def _processMessage(self, msg):
    """
    process the msg, and put the result in the output buffer
    msg (str): raw message (including header)
    """
    res = None
    wspaces = msg.count(' ')
    qmarks = msg.count('?')
    tokens = msg.split()
    if ((wspaces > 1) and (qmarks > 0)) or (wspaces > 2) or (qmarks > 1):
        res = "ERROR: Cannot parse this command\n"
    elif qmarks:
        if tokens[0] == "*IDN?":
            res = IDN + '\n'
        elif tokens[0] == "PWR?":
            pin = int(tokens[1])
            if (pin < 0) or (pin > 7):
                res = "ERROR: Out of range pin number\n"
            else:
                ans = (self._i2crcv >> pin) & MASK
                res = str(ans) + '\n'
        else:
            res = "ERROR: Cannot parse this command\n"
    elif wspaces:
        pin = int(tokens[1])
        val = int(tokens[2])
        if tokens[0] == "PWR":
            if (pin < 0) or (pin > 7):
                res = "ERROR: Out of range pin number\n"
            else:
                self._i2crcv = (self._i2crcv & ~(1 << pin)) | ((val << pin) & (1 << pin))
                res = '\n'
        elif tokens[0] == "WMEM":
            address = int(tokens[1])
            value = int(tokens[2])
            # Add logic to write value to memory at address
            res = '\n'
        elif tokens[0] == "RMEM?":
            address = int(tokens[1])
            # Add logic to read value from memory at address
            res = str(value) + '\n'  # Assuming value is retrieved
        else:
            res = "ERROR: Cannot parse this command\n"
    else:
        res = "ERROR: Cannot parse this command\n"

    # add the response end
    if res is not None:
        self._output_buf += res

def version(ctx: click.Context) -> None:
    pulp_ctx: PulpContext = ctx.find_object(PulpContext)

    # Deduce from PulpRepositoryContext
    if ctx.parent and ctx.parent.params.get("repo_type") == "file":
        ctx.obj = PulpFileRepositoryVersionContext(pulp_ctx)
    elif ctx.parent and ctx.parent.params.get("repo_type") == "repository":
        ctx.obj = PulpRepositoryVersionContext(pulp_ctx)
    else:
        raise NotImplementedError()

def __init__(self, app, pubsub, *message_types):
    self.PubSub = pubsub
    self.Loop = app.Loop

    for message_type in message_types:
        self.PubSub.subscribe(message_type, self._on_message)

    self.Websockets = set([])

async def cleanup(self):
    # Clean up during application exit:
    for ws in self.Websockets:
        await ws.close(code=WSCloseCode.GOING_AWAY, message='Server shutdown')

def create_force_refresh_endpoint(
    input_type: InputType,
    job_type: str,
    hf_endpoint: str,
    hf_token: Optional[str] = None,
    external_auth_url: Optional[str] = None,
    organization: Optional[str] = None,
) -> Endpoint:
    async def force_refresh_endpoint(request: Request) -> Response:
        try:
            dataset = request.query_params.get("dataset")
            if not are_valid_parameters([dataset]) or not dataset:
                raise MissingRequiredParameterError("Parameter 'dataset' is required")
            if input_type == "dataset":
                config = None
                split = None
            elif input_type == "config":
                config = request.query_params.get("config")
                split = None
                if not are_valid_parameters([config]):
                    raise MissingRequiredParameterError("Parameter 'config' is required")
            else:
                config = request.query_params.get("config")
                split = request.query_params.get("split")
                if not are_valid_parameters([config, split]):
                    raise MissingRequiredParameterError("Parameters 'config' and 'split' are required")
            logging.info(f"/force-refresh{job_type}, dataset={dataset}, config={config}, split={split}")

            # if auth_check fails, it will raise an exception that will be caught below
            auth_check(external_auth_url=external_auth_url, request=request, organization=organization)
            revision = get_dataset_git_revision(dataset=dataset, hf_endpoint=hf_endpoint, hf_token=hf_token)
            # ^ TODO: pass the revision to the job (meanwhile: checks if the dataset is supported)
            Queue().upsert_job(job_type=job_type, dataset=dataset, config=config, split=split, force=False, priority=Priority.NORMAL)
            return get_json_ok_response(
                {"status": "ok"},
                max_age=0,
            )
        except CustomError as e:
            return get_json_admin_error_response(e, max_age=0)
        except Exception as e:
            return get_json_admin_error_response(UnexpectedError("Unexpected error.", e), max_age=0)

    return force_refresh_endpoint

def create_from_list(self, data, constructor, error):
    """Helper function to combine the common bits of clean_target_people
       and clean_target_groups"""
    result = []
    names = [x for x in map(str.strip, re.split('[, ]+', data)) if x]
    for name in names:
        result.append(constructor(name))
    return set(result)

