def user_permissions(self, create, extracted, **kwargs):
    if not create:
        return

    if extracted:
        for permission in extracted:
            if isinstance(permission, str):
                # Support appname/model/action
                app_label, model_name, action = permission.split('.')
                permission = Permission.objects.get(codename=action, content_type__model=model_name, content_type__app_label=app_label)
            self.user_permissions.add(permission)

