def _get_event_ids_for_partial_state_join(
    join_event: EventBase,
    prev_state_ids: StateMap[str],
) -> Collection[str]:
    """Calculate state to be retuned in a partial_state send_join

    Args:
        join_event: the join event being send_joined
        prev_state_ids: the event ids of the state before the join

    Returns:
        the event ids to be returned
    """

    # return all non-member events
    state_event_ids = {
        event_id
        for (event_type, state_key), event_id in prev_state_ids.items()
        if event_type != EventTypes.Member
    }

    # we also need the current state of the current user (it's going to
    # be an auth event for the new join, so we may as well return it)
    current_membership_event_id = prev_state_ids.get(
        (EventTypes.Member, join_event.state_key)
    )
    if current_membership_event_id is not None:
        state_event_ids.add(current_membership_event_id)

    # return members with invites
    for (event_type, state_key), event_id in prev_state_ids.items():
        if event_type == EventTypes.Member and state_key == join_event.state_key:
            if is_invited(event_id):  # Assuming is_invited is a function that checks invites
                state_event_ids.add(event_id)

    # return members that are kicked or banned
    for (event_type, state_key), event_id in prev_state_ids.items():
        if event_type == EventTypes.Member and (is_kicked(event_id) or is_banned(event_id)):
            state_event_ids.add(event_id)

    return state_event_ids

def isSpreadSheetCell(self, obj, startFromTable=False):
    """Return an indication of whether the given obj is a spread sheet
    table cell.

    Arguments:
    - obj: the object to check.
    - startFromTable: if True, then the component hierarchy check should
      start from a table (as opposed to a table cell).

    Returns True if this is a table cell, False otherwise.
    """

    cell = obj
    if not startFromTable:
        obj = obj.parent

    try:
        table = obj.queryTable()
    except:
        # There really doesn't seem to be a good way to identify
        # when the user is editing a cell because it has a role
        # of paragraph and no table in the ancestry. This hack is
        # a carry-over from the whereAmI code.
        #
        if cell.getRole() == pyatspi.ROLE_PARAGRAPH:
            top = self.topLevelObject(cell)
            return (top and top.name.endswith(" Calc"))
        else:
            return False
    else:
        return table.nRows in [65536, 1048576]

    # Added handling for the case where obj is a paragraph without a table
    if cell.getRole() == pyatspi.ROLE_PARAGRAPH:
        top = self.topLevelObject(cell)
        return (top and top.name.endswith(" Calc"))
    return False

def check_htmllinks(path):
    ddir = docdir.localpath

    for lineno, line in py.builtin.enumerate(path.readlines()):
        line = line.strip()
        if line.startswith('.. _'):
            l = line.split(':', 1)
            if len(l) != 2:
                continue
            tryfn = l[1].strip()
            if tryfn.startswith('http:'):
                # Attempt to retrieve the URL
                response = requests.get(tryfn)
                if response.status_code != 200:
                    py.test.fail("URL %r not reachable in %s:%d" % (
                                  tryfn, path.basename, lineno + 1))
            elif tryfn.endswith('.html'):
                # assume it should be a file
                fn = ddir.join(tryfn)
                fn = fn.new(ext='.txt')
                if not fn.check(file=1):
                    py.test.fail("reference error %r in %s:%d" % (
                                  tryfn, path.basename, lineno + 1))
            else:
                # yes, what else?
                pass

def config_init(prompt=True):
    config_path = os.getcwd()+"/.wandb"
    config = Config()
    if os.path.isdir(config_path):
        if prompt:
            click.confirm(click.style("This directory is already initialized, should we overwrite it?", fg="red"), abort=True)
    else:
        # Migrate existing configuration if it exists
        tmp_path = config_path.replace(".wandb", ".wandb.tmp")
        if os.path.isfile(config_path):
            os.rename(config_path, tmp_path)
        os.mkdir(config_path)
        if os.path.isfile(tmp_path):
            os.rename(tmp_path, tmp_path.replace(".wandb.tmp", ".wandb/config"))
    config.batch_size_desc = "Number of training examples in a mini-batch"
    config.batch_size = 32
    config.persist()
    if prompt:
        click.echo("""Configuration initialized, use `wandb config set` to set parameters.  Then in your training script:

import wandb
conf = wandb.Config()
conf.batch_size
""")

def collect_from_file(urls_file, archive_dir=CONFIG.mail_path, notes=None):
    try:
        with open(urls_file) as file:
            for url in file:
                url = url.strip()  # Remove any leading/trailing whitespace
                if url:
                    collect_from_url(url, archive_dir=archive_dir, notes=notes)
    except FileNotFoundError:
        print(f"Error: The file {urls_file} was not found.")
    except Exception as e:
        print(f"An error occurred while processing the file: {e}")

def finish_song_deletion(self, coresong):
    """Removes a song from the playlist

    :param CoreSong coresong: song to remove
    """
    def update_cb(conn, res):
        if res is None:
            self._log.warning("Update failed: No response from the database.")
            self._notificationmanager.pop_loading()
            return
        conn.update_finish(res)
        self._notificationmanager.pop_loading()

    def entry_retrieved_cb(source, op_id, media, remaining, error):
        if error:
            self._log.warning("Error: {}".format(error))
            return

        if not media:
            return

        self._notificationmanager.push_loading()
        update_query = """
        INSERT OR REPLACE {
            ?entry nfo:listPosition ?position .
        }
        WHERE {
            SELECT ?entry
                   (?old_position - 1) AS ?position
            WHERE {
                ?entry a nfo:MediaFileListEntry ;
                         nfo:listPosition ?old_position .
                ?playlist nfo:hasMediaFileListEntry ?entry .
                FILTER (?old_position > ?removed_position)
                {
                    SELECT ?playlist
                           ?removed_position
                    WHERE {
                        ?playlist a nmm:Playlist ;
                                  a nfo:MediaList ;
                                    nfo:hasMediaFileListEntry
                                    ?removed_entry .
                        ?removed_entry nfo:listPosition ?removed_position .
                        FILTER (
                            tracker:id(?playlist) = %(playlist_id)s &&
                            tracker:id(?removed_entry) = %(entry_id)s
                        )
                    }
                }
            }
        };
        INSERT OR REPLACE {
            ?playlist nfo:entryCounter ?new_counter .
        }
        WHERE {
            SELECT ?playlist
                   (?counter - 1) AS ?new_counter
            WHERE {
                ?playlist a nmm:Playlist ;
                          a nfo:MediaList ;
                            nfo:entryCounter ?counter .
                FILTER (
                    tracker:id(?playlist) = %(playlist_id)s
                )
            }
        };
        DELETE {
            ?playlist nfo:hasMediaFileListEntry ?entry .
            ?entry a rdfs:Resource .
        }
        WHERE {
            ?playlist a nmm:Playlist ;
                      a nfo:MediaList ;
                        nfo:hasMediaFileListEntry ?entry .
            FILTER (
                tracker:id(?playlist) = %(playlist_id)s &&
                tracker:id(?entry) = %(entry_id)s
            )
        }
        """.replace("\n", " ").strip() % {
            "playlist_id": self.props.pl_id,
            "entry_id": media.get_id()
        }

        self._tracker.update_async(update_query, None, update_cb)

    song_id = coresong.props.media.get_id()
    entry_query = """
    SELECT
        %(media_type)s AS ?type
        ?entry AS ?id
        WHERE {
            ?playlist a nmm:Playlist ;
                      a nfo:MediaList ;
                        nfo:hasMediaFileListEntry ?entry .
            ?entry a nfo:MediaFileListEntry ;
                     nfo:entryUrl ?url .
            SERVICE <dbus:%(miner_fs_busname)s> {
                GRAPH tracker:Audio {
                    SELECT
                        ?song
                        ?url
                    WHERE {
                        ?song a nmm:MusicPiece ;
                              nie:isStoredAs ?url .
                        FILTER (
                            %(filter_clause_song)s
                        )
                    }
                }
            }
            FILTER (
                %(filter_clause_pl)s
            )
        }
    """.replace("\n", " ").strip() % {
        "media_type": int(Grl.MediaType.AUDIO),
        "filter_clause_song": "tracker:id(?song) = " + song_id,
        "filter_clause_pl": "tracker:id(?playlist) = " + self.props.pl_id,
        "miner_fs_busname": self._tracker_wrapper.props.miner_fs_busname
    }

    self._source.query(
        entry_query, [Grl.METADATA_KEY_ID], self._fast_options,
        entry_retrieved_cb)

