def legion_state(self, inputs, t, argv):
        index = argv;

        x = inputs[0];
        y = inputs[1];
        p = inputs[2];

        potential_influence = heaviside(p + math.exp(-self._params.alpha * t) - self._params.teta);

        #TODO: Noise should be negative!
        dx = 3 * x - x ** 3 + 2 - y + self._stimulus[index] * potential_influence + self._coupling_term[index] - self._noise[index];
        dy = self._params.eps * (self._params.gamma * (1 + math.tanh(x / self._params.betta)) - y);

        neighbors = self.get_neighbors(index);
        potential = 0;

        for index_neighbor in neighbors:
            potential += self._params.T * heaviside(self._excitatory[index_neighbor] - self._params.teta_x);

        dp = self._params.lamda * (1 - p) * heaviside(potential - self._params.teta_p) - self._params.mu * p;

        coupling = 0
        for index_neighbor in neighbors:
            coupling += self._dynamic_coupling[index][index_neighbor] * heaviside(self._excitatory[index_neighbor] - self._params.teta_x);

        self._buffer_coupling_term[index] = coupling - self._params.Wz * heaviside(self._global_inhibitor - self._params.teta_xz);

        return [dx, dy, dp];

def get_distribution_version():
    '''
    :rtype: NativeString or None
    :returns: A string representation of the version of the distribution
    '''
    distribution_version = None
    if platform.system() == 'Linux':
        try:
            distribution_version = platform.linux_distribution()[1]
            if not distribution_version and os.path.isfile('/etc/system-release'):
                distribution_version = platform.linux_distribution(supported_dists=['system'])[1]
        except Exception:
            # Using platform.dist() as a fallback for older versions
            distribution_version = platform.dist()[1] if hasattr(platform, 'dist') else None
    return distribution_version

def get_draft_validation_errors(draft_json, lot,
                                framework_id=0, slug=None, required=None):
    if not slug and not framework_id:
        raise Exception('Validation requires either framework_id or slug')
    if not slug:
        # Get framework slug from Framework table once it exists.
        framework = Framework.query.filter(
            Framework.id == framework_id
        ).first()
        slug = framework.slug if framework else None
        if slug is None:
            raise Exception('Framework not found for the given framework_id')
    errs = get_validation_errors(
        "services-{0}-{1}".format(slug, lot.lower()),
        draft_json,
        enforce_required=False,
        required_fields=required
    )
    return errs

