def tobsr(self, blocksize=None, copy=True):
    if blocksize == (1, 1):
        from bsr import bsr_matrix
        arg1 = (self.data.reshape(-1, 1, 1), self.indices, self.indptr)
        return bsr_matrix(arg1, shape=self.shape, copy=copy)
    else:
        # Optimize the conversion to BSR format
        coo = self.tocoo(copy=False)
        return bsr_matrix((coo.data, coo.row, coo.col), shape=self.shape, blocksize=blocksize, copy=copy)

