import struct

def parse_42_guid(guid):
    guid_parts = guid.split('-')
    return struct.unpack('>IIQ', bytes.fromhex(''.join(guid_parts)[:32]))

def compute_output_spec(self, x, key):
    if isinstance(key, slice):
        # Handle slicing
        if key.start is not None and key.start < 0:
            raise ValueError("Negative start index is not supported.")
        if key.stop is not None and key.stop > x.shape[0]:
            raise ValueError(f"Array has shape {x.shape} but out-of-bound index {key.stop} was requested.")
        return KerasTensor(x.shape[1:], dtype=x.dtype)
    elif not isinstance(key, int):
        raise ValueError(
            "Only scalar int keys or slices are supported at this time. Cannot "
            f"process key {key}"
        )
    if len(x.shape) == 0:
        raise ValueError(
            f"Too many indices for array: array is scalar "
            f"but index {key} was requested. A scalar array "
            "cannot be indexed."
        )
    if x.shape[0] is not None and key >= x.shape[0]:
        raise ValueError(
            f"Array has shape {x.shape} "
            f"but out-of-bound index {key} was requested."
        )
    return KerasTensor(x.shape[1:], dtype=x.dtype)

