def changes_between(
    model_type: Literal["FeatureFlag", "Person", "Insight"],
    previous: Optional[models.Model],
    current: Optional[models.Model],
) -> List[Change]:
    """
    Identifies changes between two models by comparing fields
    """
    changes: List[Change] = []

    if previous is None and current is None:
        # there are no changes between two things that don't exist
        return changes

    if previous is not None:
        fields = current._meta.fields if current is not None else []

        # Include tags in the fields assessed
        filtered_fields = [f.name for f in fields if f.name not in field_exclusions[model_type]] + ["tags"]
        for field in filtered_fields:
            left = getattr(previous, field, None)
            right = getattr(current, field, None)

            if left is None and right is not None:
                changes.append(Change(type=model_type, field=field, action="created", after=right,))
            elif right is None and left is not None:
                changes.append(Change(type=model_type, field=field, action="deleted", before=left,))
            elif left != right:
                changes.append(Change(type=model_type, field=field, action="changed", before=left, after=right,))

    return changes

def localpath(self, url, ud, d):

    ud.proto = "rsync"
    if 'protocol' in ud.parm:
        ud.proto = ud.parm['protocol']

    ud.tag = "latest"
    if 'tag' in ud.parm:
        ud.tag = ud.parm['tag']
    # FIXME, set tag to latest revision so local filestash works

    ud.localfile = data.expand('git_%s%s_%s.tar.gz' % (ud.host, ud.path.replace('/', '.'), ud.tag), d)

    return os.path.join(data.getVar("DL_DIR", d, True), ud.localfile)

def getposts(basequery=None, pinned=False, showall=False, statuses=None):
    if not statuses:
        statuses = POSTSTATUS.LISTED

    if basequery is None:
        basequery = JobPost.query

    query = basequery.filter(JobPost.status.in_(statuses)).options(*JobPost._defercols)

    if showall:
        query = query.filter(JobPost.datetime > datetime.utcnow() - agelimit)
    else:
        if pinned:
            # FIXME: Also check for g.board here
            query = query.filter(
                db.or_(
                    db.and_(JobPost.pinned == True, JobPost.datetime > datetime.utcnow() - agelimit),
                    db.and_(JobPost.pinned == False, JobPost.datetime > datetime.utcnow() - newlimit)
                )
            )  # NOQA
            if g.board:
                query = query.filter(BoardJobPost.board == g.board)
        else:
            query = query.filter(JobPost.datetime > datetime.utcnow() - newlimit)

    if g.board and g.board.name != u'www':
        query = query.join(JobPost.postboards).filter(BoardJobPost.board == g.board)

    if pinned:
        if g.board:
            query = query.order_by(db.desc(BoardJobPost.pinned))
        else:
            query = query.order_by(db.desc(JobPost.pinned))

    return query.order_by(db.desc(JobPost.datetime))

def get_stream_dailymotion(plugin,
                           video_id,
                           download_mode=False):

    # Reactivated when youtubedl is fixed
    url_dailymotion = URL_DAILYMOTION_EMBED % video_id
    return get_stream_default(plugin, url_dailymotion, download_mode)

    if download_mode:
        return False
    url_dmotion = URL_DAILYMOTION_EMBED_2 % (video_id)
    resp = urlquick.get(url_dmotion, max_age=-1)
    json_parser = json.loads(resp.text)

    if "qualities" not in json_parser:
        plugin.notify('ERROR', plugin.localize(30716))

    all_datas_videos_path = []
    if "auto" in json_parser["qualities"]:
        all_datas_videos_path.append(json_parser["qualities"]["auto"][0]["url"])
    if "144" in json_parser["qualities"]:
        all_datas_videos_path.append(json_parser["qualities"]["144"][1]["url"])
    if "240" in json_parser["qualities"]:
        all_datas_videos_path.append(json_parser["qualities"]["240"][1]["url"])
    if "380" in json_parser["qualities"]:
        all_datas_videos_path.append(json_parser["qualities"]["380"][1]["url"])
    if "480" in json_parser["qualities"]:
        all_datas_videos_path.append(json_parser["qualities"]["480"][1]["url"])
    if "720" in json_parser["qualities"]:
        all_datas_videos_path.append(json_parser["qualities"]["720"][1]["url"])
    if "1080" in json_parser["qualities"]:
        all_datas_videos_path.append(json_parser["qualities"]["1080"][1]["url"])

    url_stream = ''
    for video_path in all_datas_videos_path:
        url_stream = video_path

    manifest = urlquick.get(url_stream, max_age=-1)
    lines = manifest.text.splitlines()
    inside_m3u8 = ''
    for k in range(0, len(lines) - 1):
        if 'RESOLUTION=' in lines[k]:
            inside_m3u8 = lines[k + 1]
    return inside_m3u8.split('#cell')[0]

def send_email(config, entry, comment, comment_dir, comment_filename):
    """Send an email to the blog owner on a new comment

    @param config: configuration as parsed by Pyblosxom
    @type config: dictionary

    @param entry: a file entry
    @type config: dictionary

    @param comment: comment as generated by readComment
    @type comment: dictionary

    @param comment_dir: the comment directory
    @type comment_dir: string

    @param comment_filename: file name of current comment
    @type comment_filename: string
    """
    import smtplib
    import os
    # import the formatdate function which is in a different
    # place in Python 2.3 and up.
    try:
        from email.Utils import formatdate
    except ImportError:
        from rfc822 import formatdate

    author = escape_SMTP_commands(clean_author(comment['author']))
    description = escape_SMTP_commands(comment['description'])
    ipaddress = escape_SMTP_commands(comment.get('ipaddress', '?'))

    if comment.has_key('email'):
        email = comment['email']
    else:
        email = config['comment_smtp_from']

    try:
        server = smtplib.SMTP(config['comment_smtp_server'])
        curl = config['base_url']+'/'+entry['file_path']
        comment_dir = os.path.join(config['comment_dir'], entry['absolute_path'])

        message = []
        message.append("From: %s" % email)
        message.append("To: %s" % config["comment_smtp_to"])
        message.append("Date: %s" % formatdate(float(comment['pubDate'])))
        message.append("Subject: write back by %s" % author)
        message.append("")
        message.append("%s\n%s\n%s\n%s\n" % (description, ipaddress, comment_filename, curl))
        server.sendmail(from_addr=email,
                        to_addrs=config['comment_smtp_to'],
                        msg="\n".join(message))
        server.quit()
    except Exception as e:
        tools.log("Error sending mail: %s" % e)
        # Notify the user about the error
        print("Failed to send email: %s" % e)

def _build_log_files_from_dictionary(self, list_of_logs_in_dictionaries):
    loglist = {}
    for log in list_of_logs_in_dictionaries:
        try:
            loglist[log["name"]] = LogFile(
                log["maxdepth"], log["name"], log["timestamp"], log["binsize"], self.ip
            )
        except dateutil.parser.ParserError:
            # Log this instead of printing when logging is implemented
            logging.error(f"Could not parse timestamp for log {log['name']}, skipping this log file")
    return loglist

def __init__(self, *args):
    """
    Matrix can be constructed with values or a rule.

    >>> from sympy import Matrix, I
    >>> Matrix( ((1,2+I), (3,4)) ) #doctest:+NORMALIZE_WHITESPACE
    [1, 2 + I]
    [3,     4]
    >>> Matrix(2, 2, lambda i,j: (i+1)*j ) #doctest:+NORMALIZE_WHITESPACE
    [0, 1]
    [0, 2]

    """
    if len(args) == 3 and callable(args[2]):
        operation = args[2]
        self.rows = int(args[0])
        self.cols = int(args[1])
        self.mat = []
        for i in range(self.rows):
            for j in range(self.cols):
                self.mat.append(sympify(operation(i, j)))
    elif len(args)==3 and isinstance(args[2], (list, tuple)):
        self.rows=args[0]
        self.cols=args[1]
        mat = args[2]
        if len(mat) != self.rows*self.cols:
            raise MatrixError('List length should be equal to rows*columns')
        self.mat = map(lambda i: sympify(i), mat)
    elif len(args) == 1:
        mat = args[0]
        if isinstance(mat, Matrix):
            self.rows = mat.rows
            self.cols = mat.cols
            self.mat = mat[:]
            return
        elif hasattr(mat, "__array__"):
            arr = mat.__array__()
            if len(arr.shape) == 2:
                self.rows, self.cols = arr.shape[0], arr.shape[1]
                self.mat = map(lambda i: sympify(i), arr.ravel())
                return
            elif len(arr.shape) == 1:
                self.rows, self.cols = 1, arr.shape[0]
                self.mat = [0]*self.cols
                for i in xrange(len(arr)):
                    self.mat[i] = sympify(arr[i])
                return
            else:
                raise NotImplementedError("Sympy supports just 1D and 2D matrices")
        elif not isinstance(mat, (list, tuple)):
            raise TypeError("Matrix constructor doesn't accept %s as input" % str(type(mat)))
        self.rows = len(mat)
        if len(mat) != 0:
            if not isinstance(mat[0], (list, tuple)):
                self.cols = 1
                self.mat = map(lambda i: sympify(i), mat)
                return
            self.cols = len(mat[0])
        else:
            self.cols = 0
        self.mat = []
        for j in xrange(self.rows):
            assert len(mat[j])==self.cols
            for i in xrange(self.cols):
                self.mat.append(sympify(mat[j][i]))
    elif len(args) == 0:
        # Empty Matrix
        self.rows = self.cols = 0
        self.mat = []
    else:
        mat = args
        if not isinstance(mat[0], (list, tuple)):
            mat = [ [element] for element in mat ]
        self.rows=len(mat)
        self.cols=len(mat[0])
        self.mat=[]
        for j in xrange(self.rows):
            assert len(mat[j])==self.cols
            for i in xrange(self.cols):
                self.mat.append(sympify(mat[j][i]))

def play(self):
    appid = self.game_config.get('appid') or ''
    args = self.game_config.get('args') or ''
    logger.debug("Checking Steam installation")
    self.prepare_launch()
    env = ["WINEDEBUG=fixme-all"]
    command = []
    prefix = self.game_config.get('prefix')
    if not prefix:
        prefix = self.get_or_create_default_prefix()

    # Verify if a prefix exists that it's created with the correct architecture
    if not self.verify_prefix_architecture(prefix):
        logger.error("Prefix architecture is incorrect.")
        return {'error': 'Invalid prefix architecture'}

    env.append('WINEPREFIX="%s" ' % prefix)
    command += self.launch_args
    if appid:
        command += ['steam://rungameid/%s' % appid]
    if args:
        command += [args]
    return {'command': command, 'env': env}

