def maybe_adjust_fees(plugin: Plugin, scids: list, threshold: float = 0.1):
    for scid in scids:
        our = plugin.adj_balances[scid]["our"]
        total = plugin.adj_balances[scid]["total"]
        ratio = get_ratio(our / total)
        if abs(ratio - 1) > threshold:  # Check if the ratio is beyond the threshold
            try:
                plugin.rpc.setchannelfee(scid, int(plugin.adj_basefee * ratio),
                                         int(plugin.adj_ppmfee * ratio))
                plugin.log("Adjusted fees of {} with a ratio of {}".format(scid, ratio))
            except RpcError as e:
                plugin.log("setchannelfee error: " + str(e), level="warn")

def handler(request, path=None):
    """
    This is the default handler for feincms page content.
    """
    if path is None:
        path = request.path

    page = Page.objects.page_for_path_or_404(path)

    if not page.is_active():
        return HttpResponseNotFound('Page not found.')

    if not page.are_ancestors_active():
        return HttpResponseForbidden('Access to this page is forbidden.')

    return build_page_response(page, request)

def POST(self, req):
    """
    Handles Delete Multiple Objects.
    """
    def object_key_iter(elem):
        for obj in elem.iterchildren('Object'):
            key = obj.find('./Key').text
            if not key:
                raise UserKeyMustBeSpecified()
            version = obj.find('./VersionId')
            if version is not None:
                version = version.text

            yield key, version

    max_body_size = min(
        2 * self.conf.max_multi_delete_objects * MAX_OBJECT_NAME_LENGTH,
        10 * 1024 * 1024)

    try:
        xml = req.xml(max_body_size)
        if not xml:
            raise MissingRequestBodyError()

        req.check_md5(xml)
        elem = fromstring(xml, 'Delete', self.logger)

        quiet = elem.find('./Quiet')
        if quiet is not None and quiet.text.lower() == 'true':
            self.quiet = True
        else:
            self.quiet = False

        delete_list = list(object_key_iter(elem))
        if len(delete_list) > self.conf.max_multi_delete_objects:
            raise MalformedXML()
    except (XMLSyntaxError, DocumentInvalid):
        raise MalformedXML()
    except ErrorResponse:
        raise
    except Exception as e:
        self.logger.error(e)
        raise

    elem = Element('DeleteResult')

    # check bucket existence
    try:
        req.get_response(self.app, 'HEAD')
    except AccessDenied as error:
        body = self._gen_error_body(error, elem, delete_list)
        return HTTPOk(body=body)

    # Support deleting specific versions of objects
    for key, version in delete_list:
        if version is not None:
            # Call the do_delete function with version
            do_delete(req, key, version)
        else:
            # Call the do_delete function without version
            do_delete(req, key, None)

    body = tostring(elem)

    return HTTPOk(body=body)

def setAuthors(template, authors):
    """
    Add author information to the template document.

    Names and contact information for authors are added to each node with a
    C{class} attribute set to C{authors} and to the template head as C{link}
    nodes.

    @type template: A DOM Node or Document
    @param template: The output template which defines the presentation of the
    version information.

    @type authors: C{list} of two-tuples of C{str}
    @param authors: List of names and contact information for the authors of
    the input document.

    @return: C{None}
    """
    # First, similarly to setTitle, insert text into an <div class="authors">
    text = ''
    for name, href in authors:
        # Proper quoting/escaping using xml.sax.saxutils.escape and quoteattr
        anchor = '<a href="%s">%s</a>' % (xml.sax.saxutils.quoteattr(href), xml.sax.saxutils.escape(name))
        if (name, href) == authors[-1]:
            if len(authors) == 1:
                text = anchor
            else:
                text += 'and ' + anchor
        else:
            text += anchor + ','

    childNodes = microdom.parseString('<span>' + text +'</span>').childNodes

    for node in domhelpers.findElementsWithAttribute(template,
                                                     "class", 'authors'):
        node.childNodes.extend(childNodes)

    # Second, add appropriate <link rel="author" ...> tags to the <head>.
    head = domhelpers.findNodesNamed(template, 'head')[0]
    authors = [microdom.parseString('<link rel="author" href="%s" title="%s"/>'
                                    % (xml.sax.saxutils.quoteattr(href), xml.sax.saxutils.escape(name))).childNodes[0]
               for name, href in authors]
    head.childNodes.extend(authors)

def lookup_class(
    kind: str, apiVersion: Optional[str] = None, default: Optional[object] = None
) -> object:
    if kind in _ClassRegistry:
        return _ClassRegistry[kind]
    elif kind in _shortNameRegistry:
        className = _shortNameRegistry[kind]
    else:
        className = kind
    try:
        klass = load_class(className)
    except ImportError:
        klass = None

    if klass:
        register_class(className, klass)
    return klass

# TODO: In pandas 2.0.3 this no longer works as the dt passed in is the entire matrix and not a single date

def good_friday_unless_christmas_nye_friday(dt):
    """
    Good Friday is a valid trading day if Christmas Day or New Years Day fall
    on a Friday.
    """
    # Check if dt is a Series or a single Timestamp
    if isinstance(dt, pd.Series):
        return dt.apply(good_friday_unless_christmas_nye_friday)

    year = dt.year
    christmas_weekday = Christmas.observance(
        pd.Timestamp(year, 12, 25)
    ).weekday()
    nyd_weekday = USNewYearsDay.observance(
        pd.Timestamp(year, 1, 1)
    ).weekday()
    if christmas_weekday != 4 and nyd_weekday != 4:
        return GoodFriday._apply_rule(dt)
    else:
        # compatibility for pandas 0.18.1
        return pd.NaT

def execute(self, context):

    # get list of selected objects
    obj_list = context.selected_objects
    if not obj_list:
        self.report({'ERROR'}, "No objects selected")
        return {'CANCELLED'}

    # gets the list of materials (without repetition) from selected
    mat_list = util.materialsFromObj(obj_list)
    if not mat_list:
        self.report({'ERROR'}, "No materials found on selected objects")
        return {'CANCELLED'}

    # check if linked material exists
    engine = context.scene.render.engine
    count = 0

    for mat in mat_list:
        # Check if the material is linked
        is_linked_material = mat.use_fake_user or (mat.library is not None)

        passes = generate.get_textures(mat)
        if not self.useExtraMaps:
            for pass_name in passes:
                if pass_name != "diffuse":
                    passes[pass_name] = None
        if self.autoFindMissingTextures:
            for pass_name in passes:
                res = generate.replace_missing_texture(passes[pass_name])
                if res > 0:
                    mat["texture_swapped"] = True  # used to apply saturation

        if is_linked_material:
            # Handle linked materials differently if needed
            self.report({'WARNING'}, "Linked material detected: {}".format(mat.name))
            # Add any specific handling for linked materials here
            continue  # Skip further processing for linked materials

        if engine == 'BLENDER_RENDER' or engine == 'BLENDER_GAME':
            res = generate.matprep_internal(mat, passes,
                self.useReflections, self.makeSolid)
            if res == 0:
                count += 1
            if self.animateTextures:
                sequences.animate_single_material(
                    mat, context.scene.render.engine)
        elif engine == 'CYCLES' or engine == 'BLENDER_EEVEE':
            res = generate.matprep_cycles(mat, passes, self.useReflections,
                self.usePrincipledShader, self.makeSolid)
            if res == 0:
                count += 1
            if self.animateTextures:
                sequences.animate_single_material(
                    mat, context.scene.render.engine)
        else:
            self.report({'ERROR'}, "Only blender internal or cycles supported")
            return {'CANCELLED'}

    if self.combineMaterials is True:
        bpy.ops.mcprep.combine_materials(selection_only=True, skipUsage=True)
    if self.improveUiSettings:
        bpy.ops.mcprep.improve_ui()
    self.report({"INFO"}, "Modified " + str(count) + " materials")
    self.track_param = context.scene.render.engine
    self.track_exporter = generate.detect_form(mat_list)
    return {'FINISHED'}

