def get_metric(name):

    try:
        return METRIC_REGISTRY[name]
    except KeyError:
        # Changed print to logging
        logging.warning(
            f"Could not find registered metric '{name}' in lm-eval, \
searching in HF Evaluate library..."
        )
        try:
            metric_object = evaluate.load(name)
            return metric_object.compute
        except Exception:
            eval_logger.error(
                "{} not found in the evaluate library!".format(name),
                "Please check https://huggingface.co/evaluate-metric",
            )

def add_image(self, can_remove = True):
    '''Add an image to be measured'''
    # XXX needs to use cps.SettingGroup
    class ImageSettings(cps.SettingGroup):
        '''Settings describing an image to be measured'''
        def __init__(self, images):
            super().__init__()
            self.key = uuid.uuid4()
            self.image_name = cps.ImageNameSubscriber(
                "Select the input image", "None")
            if can_remove:
                def remove(images=images, key = self.key):
                    index = [x.key for x in images].index(key)
                    del images[index]
                self.remove_button = cps.DoSomething("Remove above image",
                                                     "Remove", remove)
        def settings(self):
            '''Return the settings that should be saved in the pipeline'''
            return [self.image_name]

        def visible_settings(self):
            '''Return the settings that should be displayed'''
            if can_remove:
                return [self.image_name, self.remove_button]
            else:
                return [self.image_name]
    self.images.append(ImageSettings(self.images))

def get_package_members(
    package: db_models.Package = Depends(get_package_or_fail),
    dao: Dao = Depends(get_dao),
):

    member_list = dao.get_package_members(package.channel.name, package.name)

    for member in member_list:
        # force loading of profile before changing attributes to prevent sqlalchemy errors.
        member.user.profile  # Load profile to avoid SQLAlchemy errors
        # Instead of modifying the user model directly, create a new user object
        user_id = str(uuid.UUID(bytes=member.user.id))
        member.user = User(id=user_id, profile=member.user.profile)  # Assuming User is a valid model

    return member_list

def hover_response_for_position(
    self, path: Path, position: lsp.LspPosition
) -> lsp.HoverResponse:
    # Look up the type.
    type_info = self.lookup_type(path, position)  # Assuming a method to look up type
    return lsp.HoverResponse(contents=type_info)

def spawn_locusts(self, spawn_count=None, stop_timeout=None, wait=False):
    if spawn_count is None:
        spawn_count = self.num_clients

    if self.num_requests is not None:
        RequestStats.global_max_requests = self.num_requests

    bucket = self.weight_locusts(spawn_count, stop_timeout)
    spawn_count = len(bucket)
    if self.state == STATE_INIT or self.state == STATE_STOPPED:
        self.state = STATE_HATCHING
        self.num_clients = spawn_count
    else:
        self.num_clients += spawn_count

    logger.info("Hatching and swarming %i clients at the rate %g clients/s..." % (spawn_count, self.hatch_rate))
    occurence_count = dict([(l.__name__, 0) for l in self.locust_classes])

    def hatch():
        sleep_time = 1.0 / self.hatch_rate
        while True:
            if not bucket:
                logger.info("All locusts hatched: %s" % ", ".join(["%s: %d" % (name, count) for name, count in occurence_count.iteritems()]))
                events.hatch_complete.fire(self.num_clients)
                return

            locust = bucket.pop(random.randint(0, len(bucket)-1))
            occurence_count[locust.__name__] += 1
            def start_locust(_):
                try:
                    locust().run()
                except GreenletExit:
                    pass
            new_locust = self.locusts.spawn(start_locust, locust)
            if len(self.locusts) % 10 == 0:
                logger.debug("%i locusts hatched" % len(self.locusts))
            gevent.sleep(sleep_time)

    hatch()
    if wait:
        self.locusts.join()
        logger.info("All locusts dead\n")
        # Using an event listener for printing percentile stats
        events.percentile_stats_complete.add(lambda: print_percentile_stats(self.request_stats))
        events.percentile_stats_complete.fire()

def create(entity_type=None, entity_id=None):
    if not (entity_id or entity_type):
        for allowed_type in ENTITY_TYPES:
            if mbid := request.args.get(allowed_type):
                entity_type = allowed_type
                entity_id = mbid
                break

        if entity_type:
            return redirect(url_for('.create', entity_type=entity_type, entity_id=entity_id))

        flash.info(gettext("Please choose an entity to review."))
        return redirect(url_for('search.selector', next=url_for('.create')))

    if entity_type not in ENTITY_TYPES:
        raise BadRequest("You can't write reviews about this type of entity.")

    if current_user.is_blocked:
        flash.error(gettext("You are not allowed to write new reviews because your "
                            "account has been blocked by a moderator."))
        return redirect(url_for('user.reviews', user_id=current_user.id))

    # Checking if the user already wrote a review for this entity
    reviews, count = db_review.list_reviews(user_id=current_user.id, entity_id=entity_id, inc_drafts=True, inc_hidden=True)
    review = reviews[0] if count != 0 else None

    if review:
        if review['is_draft']:
            return redirect(url_for('review.edit', id=review['id']))
        elif review['is_hidden']:
            return redirect(url_for('review.entity', id=review['id']))
        else:
            flash.error(gettext("You have already published a review for this entity"))
            return redirect(url_for('review.entity', id=review["id"]))

    if current_user.is_review_limit_exceeded:
        flash.error(gettext("You have exceeded your limit of reviews per day."))
        return redirect(url_for('user.reviews', user_id=current_user.id))

    form = ReviewCreateForm(default_license_id=current_user.license_choice, default_language=get_locale())

    if form.validate_on_submit():
        is_draft = form.state.data == 'draft'
        if form.text.data == '':
            form.text.data = None
        review = db_review.create(user_id=current_user.id, entity_id=entity_id, entity_type=entity_type,
                                  text=form.text.data, rating=form.rating.data, license_id=form.license_choice.data,
                                  language=form.language.data, is_draft=is_draft)
        if form.remember_license.data:
            db_users.update(current_user.id, user_new_info={
                "license_choice": form.license_choice.data,
            })
        if is_draft:
            flash.success(gettext("Review has been saved!"))
        else:
            flash.success(gettext("Review has been published!"))
        return redirect(url_for('.entity', id=review['id']))

    try:
        _entity = get_entity_by_id(entity_id, entity_type)
        data = {
            "form": form,
            "entity_type": entity_type,
            "entity": _entity,
        }
    except NoDataFoundException:
        flash.error(gettext("You can only write a review for an entity that exists on MusicBrainz!"))
        return redirect(url_for('search.selector', next=url_for('.create')))

    data["entity_title"] = get_entity_title(_entity)
    if entity_type == "release_group":
        data["spotify_mappings"] = mbspotify.mappings(entity_id)
        data["soundcloud_url"] = soundcloud.get_url(entity_id)

    if not form.errors:
        flash.info(gettext("Please provide some text or a rating for this review."))
    return render_template('review/modify/write.html', **data)

def excerpt(self, source_paths, workdir, conform):
    '''

        Tested version from openaddr.excerpt() on master branch:

        if ext == '.zip':
            _L.debug('Downloading all of {cache}'.format(**extras))

            with open(cachefile, 'w') as file:
                for chunk in got.iter_content(1024**2):
                    file.write(chunk)

            zf = ZipFile(cachefile, 'r')

            for name in zf.namelist():
                _, ext = splitext(name)

                if ext in ('.shp', '.shx', '.dbf'):
                    with open(join(workdir, 'cache'+ext), 'w') as file:
                        file.write(zf.read(name))

            if exists(join(workdir, 'cache.shp')):
                ds = ogr.Open(join(workdir, 'cache.shp'))
            else:
                ds = None

        elif ext == '.json':
            _L.debug('Downloading part of {cache}'.format(**extras))

            scheme, host, path, query, _, _ = urlparse(got.url)

            if scheme in ('http', 'https'):
                conn = HTTPConnection(host, 80)
                conn.request('GET', path + ('?' if query else '') + query)
                resp = conn.getresponse()
            elif scheme == 'file':
                with open(path) as rawfile:
                    resp = StringIO(rawfile.read(1024*1024))
            else:
                raise RuntimeError('Unsure what to do with {}'.format(got.url))

            with open(cachefile, 'w') as file:
                file.write(sample_geojson(resp, 10))

            ds = ogr.Open(cachefile)

        else:
            ds = None
    '''
    encoding = conform.get('encoding')
    csvsplit = conform.get('csvsplit', ',')

    known_paths = ExcerptDataTask._get_known_paths(source_paths, workdir, conform, self.known_types)

    if not known_paths:
        # we know nothing.
        return None, None

    data_path = known_paths[0]
    _, data_ext = os.path.splitext(data_path.lower())

    # Sample a few GeoJSON features to save on memory for large datasets.
    if data_ext in ('.geojson', '.json'):
        data_path = ExcerptDataTask._sample_geojson_file(data_path)

    # Use 'format' instead of deprecated 'type'
    format_string = conform.get('format')

    # GDAL has issues with weird input CSV data, so use Python instead.
    if format_string == 'csv':
        return ExcerptDataTask._excerpt_csv_file(data_path, encoding, csvsplit)

    ogr_data_path = normalize_ogr_filename_case(data_path)
    datasource = ogr.Open(ogr_data_path, 0)
    layer = datasource.GetLayer()

    if not encoding:
        encoding = guess_source_encoding(datasource, layer)

    # GDAL has issues with non-UTF8 input CSV data, so use Python instead.
    if data_ext == '.csv' and encoding not in ('utf8', 'utf-8'):
        return ExcerptDataTask._excerpt_csv_file(data_path, encoding, csvsplit)

    layer_defn = layer.GetLayerDefn()
    fieldcount = layer_defn.GetFieldCount()
    fieldnames = [layer_defn.GetFieldDefn(i).GetName() for i in range(fieldcount)]
    fieldnames = [f.decode(encoding) if hasattr(f, 'decode') else f for f in fieldnames]

    data_sample = [fieldnames]

    for (feature, _) in zip(layer, range(5)):
        row = [feature.GetField(i) for i in range(fieldcount)]
        row = [v.decode(encoding) if hasattr(v, 'decode') else v for v in row]
        data_sample.append(row)

    if len(data_sample) < 2:
        raise ValueError('Not enough rows in data source')

    # Determine geometry_type from layer, sample, or give up.
    if layer_defn.GetGeomType() in geometry_types:
        geometry_type = geometry_types.get(layer_defn.GetGeomType(), None)
    elif fieldnames[-3:] == [X_FIELDNAME, Y_FIELDNAME, GEOM_FIELDNAME]:
        geometry = ogr.CreateGeometryFromWkt(data_sample[1][-1])
        geometry_type = geometry_types.get(geometry.GetGeometryType(), None)
    else:
        geometry_type = None

    return data_sample, geometry_type

def __init__(
    self,
    model: openvino.runtime.Model,
    parent_model: OVBaseModel,
    ov_config: Optional[Dict[str, str]] = None,
    model_name: str = "encoder",
    model_dir: str = None,
):
    self.model = model
    self.parent_model = parent_model
    self.input_names = {key.get_any_name(): idx for idx, key in enumerate(self.model.inputs)}
    self.input_dtype = {
        inputs.get_any_name(): OV_TO_NP_TYPE[inputs.get_element_type().get_type_name()]
        for inputs in self.model.inputs
    }
    self.ov_config = ov_config or {**self.parent_model.ov_config}
    self.request = None
    self._model_name = model_name
    self._model_dir = Path(model_dir or parent_model._model_save_dir)
    config_path = self._model_dir / model_name / self.CONFIG_NAME
    self.config = self.parent_model._dict_from_json_file(config_path) if config_path.is_file() else {}

    # TODO : disable if self._model_dir tmp directory
    if "CACHE_DIR" not in self.ov_config and "tmp" not in str(self._model_dir):
        self.ov_config["CACHE_DIR"] = os.path.join(self._model_dir, self._model_name)

