def _update_job(self, job_id, state=None, **kwargs):
    from copy import copy
    with self.session_scope() as session:
        try:
            job, orm_job = self._get_job_and_orm_job(job_id, session)
            # Our hack here is to just copy the job object, and then set the specific
            # field we want to edit, in this case the job.state. That forces
            # SQLAlchemy to re-pickle the object, thus setting it to the correct state.
            job_copy = copy(job)
            if state is not None:
                orm_job.state = job_copy.state = state
            for kwarg in kwargs:
                setattr(job_copy, kwarg, kwargs[kwarg])
            orm_job.obj = job_copy
            session.add(orm_job)
            return job_copy, orm_job
        except JobNotFound:
            if state:
                logger.error(
                    "Tried to update job with id {} with state {} but it was not found".format(
                        job_id, state
                    )
                )
            else:
                logger.error(
                    "Tried to update job with id {} but it was not found".format(
                        job_id
                    )
                )

def get_sequence(self, name):
    """
    Returns the saved Pulse_Sequence object by name without setting it as current sequence
    """
    if name in self.saved_sequences:
        with open(self.sequence_dir + name + '.seq', 'rb') as infile:
            sequence = pickle.load(infile)
    else:
        raise FileNotFoundError(f'Error: No sequence with name "{name}" in saved sequences.')
    return sequence

def __str__(self):
    modifiers = ' '.join(self.type_modifiers)
    syntax = ''
    if self.reference:
        syntax += '&'
    if self.pointer:
        syntax += '*'
    templated_types = '<%s>' % ', '.join(self.templated_types) if self.templated_types else ''
    suffix = '%s %s%s %s%s' % (modifiers, self.type_name, syntax, templated_types, self.name)
    if self.default:
        suffix += ' = ' + self.default
    return self._StringHelper(self.__class__.__name__, suffix)

def SBROM_KeyDerivation(self, aeskeytype, key, salt, requestedlen, destaddr):
    result = bytearray()
    buffer = bytearray(b"\x00" * 0x43)
    if aeskeytype - 1 > 4 or (1 << (aeskeytype - 1) & 0x17) == 0:
        return 0xF2000002
    if requestedlen > 0xFF or (requestedlen << 28) & 0xFFFFFFFF:
        return 0xF2000003
    if 0x0 >= len(key) > 0x20:
        return 0xF2000003
    bufferlen = len(salt) + 3 + len(key)
    iterlength = (requestedlen + 0xF) >> 4
    if len(key) == 0:
        keyend = 1
    else:
        buffer[1:1 + len(key)] = key
        keyend = len(key) + 1
    saltstart = keyend + 1
    if len(salt) > 0:
        buffer[saltstart:saltstart + len(salt)] = salt
    # Verify buffer structure
    if len(buffer) < saltstart + len(salt) + 4:
        return 0xF2000004  # Buffer too small
    buffer[saltstart + len(salt):saltstart + len(salt) + 4] = pack("<I", 8 * requestedlen)
    for i in range(0, iterlength):
        buffer[0] = i + 1
        dstaddr = self.SBROM_AesCmac(aeskeytype, 0x0, buffer, 0, bufferlen, destaddr)
        if dstaddr != 0:
            for field in self.read32(dstaddr + 0x108, 4):
                result.extend(pack("<I", field))
    return result

def decrypt(self, encryption_context):
    # Refuse decode if EncryptionContext is not the same as when it was encrypted / generated
    if self.parameters.get("EncryptionContext") != encryption_context:
        raise ValueError("Invalid EncryptionContext")

    value = self.parameters.get("CiphertextBlob")
    try:
        return json.dumps({"Plaintext": base64.b64decode(value).decode("utf-8"), 'KeyId': 'key_id'})
    except UnicodeDecodeError:
        # Generate data key will produce random bytes which when decrypted is still returned as base64
        return json.dumps({"Plaintext": value})

def visit_Ac_Implied_Do(self, o, **kwargs):
    """
    An implied-do for array constructors
    """
    # Implementing implied-do logic
    if hasattr(o, 'items'):
        children = [self.visit(a, **kwargs) for c in o.items for a in as_tuple(c)]
        return children if children else None
    return self.visit_Base(o, **kwargs)

def primary_key(self):
    from kart.working_copy import gpkg_adapter
    from kart.working_copy import other_adapter  # Import other adapter for different formats

    with self.engine.connect() as conn:
        if self.is_gpkg():  # Check if the format is GPKG
            return gpkg_adapter.pk(conn, self.table)
        else:
            return other_adapter.pk(conn, self.table)  # Call the appropriate method for other formats

    def is_gpkg(self):
        # Logic to determine if the current table is in GPKG format
        return self.table.endswith('.gpkg')  # Example check based on table name

