def __valueDoubleClick( self, widget, event ) :

    if event.button != event.Buttons.Left :
        return False

    if not self.__inspectorResults :
        return False

    if all( r.editable() for r in self.__inspectorResults ) :

        self.__popup = GafferUI.PlugPopup(
            list( { r.acquireEdit() for r in self.__inspectorResults } ),
            warning = self.__formatWarnings(
                [ r.editWarning() for r in self.__inspectorResults ]
            )
        )
        if isinstance( self.__popup.plugValueWidget(), GafferSceneUI.TweakPlugValueWidget ) :
            self.__popup.plugValueWidget().setNameVisible( False )
        self.__popup.popup()

    else :

        # See todo in `PlugPopup._PopupWindow`
        self.__popup = GafferUI.PlugPopup(
            [],
            warning = self.__formatWarnings(
                [ r.nonEditableReason() for r in self.__inspectorResults ]
            )
        )
        with self.__popup :
            with GafferUI.ListContainer( GafferUI.ListContainer.Orientation.Horizontal, spacing = 4 ) :
                GafferUI.Image( "warningSmall.png" )
                GafferUI.Label( "<h4>{}</h4>".format(
                    self.__formatWarnings( [ r.nonEditableReason() for r in self.__inspectorResults ] )
                ) )

        self.__popup.popup()

    return True

def visit_Module(self, node) -> str:
    docstring = getattr(node, "docstring_comment", None)
    buf = [self.comment(docstring.value)] if docstring is not None else []
    filename = getattr(node, "__file__", None)
    if filename is not None:
        self._module = Path(filename).stem
    # Generalize this to reset all state that needs to be reset
    self.reset_state()  # New method to reset all necessary state
    body_dict: Dict[ast.AST, str] = OrderedDict()
    for b in node.body:
        if not isinstance(b, ast.FunctionDef):
            body_dict[b] = self.visit(b)
    # Second pass to handle functiondefs whose body
    # may refer to other members of node.body
    for b in node.body:
        if isinstance(b, ast.FunctionDef):
            body_dict[b] = self.visit(b)

    buf += [body_dict[b] for b in node.body]
    return "\n".join(buf)

# New method to reset all necessary state
def reset_state(self):
    self._imported_names = {}
    self._usings.clear()

def _check_error(self, value):
    if value != CKR_OK:
        if value in ERROR_CODES:
            raise P11CryptoPluginException(u._(
                "HSM returned response code: {hex_value} {code}").format(
                    hex_value=hex(value),
                    code=ERROR_CODES.get(value, 'CKR_????')))
        else:
            raise P11CryptoPluginException(u._(
                "HSM returned an unknown response code: {hex_value}").format(
                    hex_value=hex(value)))

def run_job(job_id):
    job = fetch('Job', id=job_id)
    if job.status == 'Running':
        return {'error': 'Job is already running.'}
    targets = job.compute_targets()
    if hasattr(job, 'has_targets'):
        if job.has_targets and not targets:
            return {'error': 'Set devices or pools as targets first.'}
        if not job.has_targets and targets:
            return {'error': 'This service should not have targets configured.'}
    # Request to REST API
    response = requests.post('http://api.example.com/jobs', json=job.serialized)
    if response.status_code != 200:
        return {'error': 'Failed to request REST API.'}
    return job.serialized

def download(self, globus=True, verbose=False, **kwargs):
    """Download a Foundry dataset
    Args:
        globus (bool): if True, use Globus to download the data else try HTTPS
        verbose (bool): if True print out debug information during the download

    Returns
    -------
    (Foundry): self: for chaining
    """
    # Check if the dir already exists
    path = os.path.join(self.config.local_cache_dir, self.mdf["source_id"])

    if os.path.isdir(path):
        # if directory is present, but doesn't have the correct number of files inside,
        # dataset will attempt to redownload
        if self.dataset.splits:
            # array to keep track of missing files
            missing_files = []
            for split in self.dataset.splits:
                if split.path[0] == '/':
                    split.path = split.path[1:]
                if not os.path.isfile(os.path.join(path, split.path)):
                    missing_files.append(split.path)
            # if number of missing files is greater than zero, redownload with informative message
            if len(missing_files) > 0:
                logger.info(f"Dataset will be redownloaded, following files are missing: {missing_files}")
            else:
                return self
        else:
            # in the case of no splits, ensure the directory contains at least one file
            if (len(os.listdir(path)) >= 1):
                return self
            else:
                logger.info("Dataset will be redownloaded, expected file is missing")

    res = self.forge_client.search(
        f"mdf.source_id:{self.mdf['source_id']}", advanced=True
    )
    if globus:
        self.forge_client.globus_download(
            res,
            dest=self.config.local_cache_dir,
            dest_ep=self.config.destination_endpoint,
            interval=kwargs.get("interval", 20),
            download_datasets=True,
        )
    else:
        https_config = {
            "source_ep_id": "82f1b5c6-6e9b-11e5-ba47-22000b92c6ec",
            "base_url": "https://data.materialsdatafacility.org",
            "folder_to_crawl": f"/foundry/{self.mdf['source_id']}/",
            "source_id": self.mdf["source_id"]
        }

        task_list = list(recursive_ls(self.transfer_client,
                                      https_config['source_ep_id'],
                                      https_config['folder_to_crawl']))
        # Add parallel download
        with concurrent.futures.ThreadPoolExecutor() as executor:
            futures = {executor.submit(download_file, task, https_config): task for task in task_list}
            for future in concurrent.futures.as_completed(futures):
                task = futures[future]
                try:
                    future.result()
                except Exception as e:
                    logger.error(f"Error downloading {task['name']}: {e}")

    # after download check making sure directory exists, contains all indicated files
    if os.path.isdir(path):
        # checking all necessary files are present
        if self.dataset.splits:
            missing_files = []
            for split in self.dataset.splits:
                if split.path[0] == '/':  # if absolute path, make it a relative path
                    split.path = split.path[1:]
                if not os.path.isfile(os.path.join(path, split.path)):
                    # keeping track of all files not downloaded
                    missing_files.append(split.path)
            if len(missing_files) > 0:
                raise FileNotFoundError(f"Downloaded directory does not contain the following files: {missing_files}")

        else:
            if (len(os.listdir(path)) < 1):
                raise FileNotFoundError("Downloaded directory does not contain the expected file")
    else:
        raise NotADirectoryError("Unable to create directory to download data")

    return self

def __init__(self, task_list, filter_=None):

    self.filter = filter_
    self.targets = {}
    # name of task in order to be executed
    # this the order as in the dodo file. the real execution
    # order might be different if the dependecies require so.
    self.task_order = []
    # dict of tasks by name
    self.tasks = {}

    # sanity check and create tasks dict
    for task in task_list:
        # task must be a BaseTask
        if not isinstance(task, BaseTask):
            msg = "Task must an instance of BaseTask class. %s"
            raise InvalidTask(msg % (task.__class__))
        # task name must be unique
        if task.name in self.tasks:
            msg = "Task names must be unique. %s"
            raise InvalidDodoFile(msg % task.name)

        self.tasks[task.name] = task
        self.task_order.append(task.name)


    # check task-dependencies exist.
    for task in self.tasks.values():
        for dep in task.task_dep:
            if dep not in self.tasks:
                msg = "%s. Task dependency '%s' does not exist."
                raise InvalidTask(msg% (task.name,dep))

    # get target dependecies on other tasks based on file dependency on
    # a target.
    # 1) create a dictionary associating every target->task. where the task
    # builds that target.
    for task in self.tasks.values():
        for target in task.targets:
            # Check if the target already has an associated task
            if target in self.targets:
                msg = "Multiple tasks cannot build the same target: %s"
                raise InvalidTask(msg % target)
            self.targets[target] = task
    # 2) now go through all dependencies and check if they are target from
    # another task.
    for task in self.tasks.values():
        for dep in task.file_dep:
            if (dep in self.targets and
                self.targets[dep] not in task.task_dep):
                task.task_dep.append(self.targets[dep].name)

def setJobAttribute( self, jobID, attrName, attrValue, update = False, myDate = None ):  
  """ Set an attribute value for job specified by jobID.  
      The LastUpdate time stamp is refreshed if explicitly requested  
  """  

  ret = self._escapeString( jobID )  
  if not ret['OK']:  
    return ret  
  jobID = ret['Value']  

  ret = self._escapeString( attrValue )  
  if not ret['OK']:  
    return ret  
  value = ret['Value']  

  # Check the validity of attrName  
  valid_attr_names = ['attr1', 'attr2', 'attr3']  # Replace with actual valid attribute names  
  if attrName not in valid_attr_names:  
    return S_ERROR('Invalid attribute name: %s' % attrName)  

  if update:  
    cmd = "UPDATE Jobs SET %s=%s,LastUpdateTime=UTC_TIMESTAMP() WHERE JobID=%s" % ( attrName, value, jobID )  
  else:  
    cmd = "UPDATE Jobs SET %s=%s WHERE JobID=%s" % ( attrName, value, jobID )  

  if myDate:  
    cmd += ' AND LastUpdateTime < %s' % myDate  

  res = self._update( cmd )  
  if res['OK']:  
    return res  
  else:  
    return S_ERROR( 'JobDB.setAttribute: failed to set attribute' )

def get_site_coordination_environment(
    self,
    site,
    isite=None,
    dequivsite=None,
    dthissite=None,
    mysym=None,
    return_map=False,
):
    """
    Retrieves the coordination environment for a given site in the structure.

    :param site: The site for which to retrieve the coordination environment.
    :param isite: The index of the site in the structure (optional).
    :param dequivsite: The translation to the equivalent site (optional).
    :param dthissite: The translation to the current site (optional).
    :param mysym: The symmetry operation applied to the site (optional).
    :param return_map: Whether to return the coordination number map (default: False).
    :return: The coordination environment or None if not found.
    """
    if isite is None:
        [
            isite,
            dequivsite,
            dthissite,
            mysym,
        ] = self.equivalent_site_index_and_transform(site)
    neighbors_normalized_distances = self.structure_environments.voronoi.neighbors_normalized_distances[isite]
    neighbors_normalized_angles = self.structure_environments.voronoi.neighbors_normalized_angles[isite]
    idist = None
    for iwd, wd in enumerate(neighbors_normalized_distances):
        if self.distance_cutoff >= wd["min"]:
            idist = iwd
        else:
            break
    iang = None
    for iwa, wa in enumerate(neighbors_normalized_angles):
        if self.angle_cutoff <= wa["max"]:
            iang = iwa
        else:
            break
    if idist is None or iang is None:
        raise ValueError("Distance or angle parameter not found ...")

    my_cn = None
    my_inb_set = None
    found = False
    for cn, nb_sets in self.structure_environments.neighbors_sets[isite].items():
        for inb_set, nb_set in enumerate(nb_sets):
            sources = [
                src
                for src in nb_set.sources
                if src["origin"] == "dist_ang_ac_voronoi" and src["ac"] == self.additional_condition
            ]
            for src in sources:
                if src["idp"] == idist and src["iap"] == iang:
                    my_cn = cn
                    my_inb_set = inb_set
                    found = True
                    break
            if found:
                break
        if found:
            break

    if not found:
        return None

    cn_map = (my_cn, my_inb_set)
    ce = self.structure_environments.ce_list[self.structure_environments.sites_map[isite]][cn_map[0]][cn_map[1]]
    if ce is None:
        return None
    coord_geoms = ce.coord_geoms
    if return_map:
        if coord_geoms is None:
            return cn_map[0], cn_map
        return (
            ce.minimum_geometry(symmetry_measure_type=self._symmetry_measure_type),
            cn_map,
        )
    if coord_geoms is None:
        return cn_map[0]
    return ce.minimum_geometry(symmetry_measure_type=self._symmetry_measure_type)

def parseTargetDirect():
    """
    Parse target dbms and set some attributes into the configuration singleton.
    """

    if not conf.direct:
        return

    details = None

    for dbms in SUPPORTED_DBMS:
        details = re.search("^(?P<dbms>%s)://(?P<credentials>(?P<dbmsUser>.+?)\:(?P<dbmsPass>.+?)\@)?(?P<remote>(?P<hostname>.+?)\:(?P<port>[\d]+)\/)?(?P<dbmsDb>.+?)$" % dbms, conf.direct, re.I)

        if details:
            conf.dbms     = details.group('dbms')

            if details.group('credentials'):
                conf.dbmsUser = details.group('dbmsUser')
                conf.dbmsPass = details.group('dbmsPass')
            else:
                conf.dbmsUser = str()
                conf.dbmsPass = str()

            if details.group('remote'):
                conf.hostname = details.group('hostname')
                conf.port     = int(details.group('port'))
            else:
                conf.hostname = "localhost"
                conf.port     = 0

            conf.dbmsDb   = details.group('dbmsDb')

            conf.parameters[None] = "direct connection"

            break

    if not details:
        errMsg = "invalid target details, valid syntax is for instance: 'mysql://USER:PASSWORD@DBMS_IP:DBMS_PORT/DATABASE_NAME'"
        errMsg += " and/or: 'access://DATABASE_FILEPATH'"
        raise sqlmapSyntaxException, errMsg

    # TODO: add details for others python DBMS libraries
    dbmsDict = { "Microsoft SQL Server": [MSSQL_ALIASES, "python-pymssql", "http://pymssql.sourceforge.net/"],
                 "MySQL": [MYSQL_ALIASES, "python-mysqldb", "http://mysql-python.sourceforge.net/"],
                 "PostgreSQL": [PGSQL_ALIASES, "python-psycopg2", "http://initd.org/psycopg/"],
                 "Oracle": [ORACLE_ALIASES, "python cx_Oracle", "http://cx-oracle.sourceforge.net/"],
                 "SQLite": [SQLITE_ALIASES, "", ""],
                 "Access": [ACCESS_ALIASES, "", ""],
                 "Firebird": [FIREBIRD_ALIASES, "", ""],
                 "MongoDB": [MONGODB_ALIASES, "pymongo", "https://pymongo.readthedocs.io/"] }

    for dbmsName, data in dbmsDict.items():
        if conf.dbms in data[0]:
            try:
                if dbmsName == "Microsoft SQL Server":
                    import pymssql
                elif dbmsName == "MySQL":
                    import MySQLdb
                elif dbmsName == "PostgreSQL":
                    import psycopg2
                elif dbmsName == "Oracle":
                    import cx_Oracle
                elif dbmsName == "MongoDB":
                    import pymongo
            except ImportError, _:
                errMsg  = "sqlmap requires %s third-party library " % data[1]
                errMsg += "in order to directly connect to the database "
                errMsg += "%s. Download from %s" % (dbmsName, data[2])
                raise sqlmapMissingDependence, errMsg

def aistudio_download(repo_id: str, filename: str, cache_dir: str = None, revision: str = None):
    # TODO: add arguments such as cache_dir, revision, etc.
    res = download(
        repo_id=repo_id,
        filename=filename,
        cache_dir=cache_dir,
        revision=revision
    )
    if "path" in res:
        return res["path"]
    else:
        if res["error_code"] == 10001:
            raise ValueError("Illegal argument error")
        elif res["error_code"] == 10002:
            raise UnauthorizedError(
                "Unauthorized Access. Please ensure that you have provided the AIStudio Access Token and you have access to the requested asset"
            )
        elif res["error_code"] == 12001:
            raise EntryNotFoundError(f"Cannot find the requested file '{filename}' in repo '{repo_id}'")
        else:
            raise Exception(f"Unknown error: {res}")

