def set_tag_end_ms(tag, end_ms):
    """
    Sets the end timestamp for a tag.

    Should only be called by change_tag_expiration or tests.
    """

    with db_transaction():
        updated = (
            Tag.update(lifetime_end_ms=end_ms)
            .where(Tag.id == tag)
            .where(Tag.lifetime_end_ms == tag.lifetime_end_ms)
            .execute()
        )
        if updated != 1:
            return (None, False)

        return (tag.lifetime_end_ms, True)

def announce(self, negotiated, nlris=None, mps=None):
    asn4 = negotiated.asn4
    local_as = negotiated.local_as
    peer_as = negotiated.peer_as
    msg_size = negotiated.msg_size

    attr = self.attributes.pack(asn4, local_as, peer_as)

    if nlris is None and mps is None:
        packed_nlri = []
        packed_mp = []

        for nlri in self.nlris:
            afi, safi = nlri.afi, nlri.safi
            addpath = negotiated.addpath.send(afi, safi)

            if nlri.family() in negotiated.families:
                if afi == AFI.ipv4 and safi in [SAFI.unicast, SAFI.multicast] and nlri.nexthop == self.attributes.get(AID.NEXT_HOP, None):
                    packed_nlri.append(nlri)
                else:
                    packed_mp.append(nlri)
    else:
        packed_nlri = nlris
        packed_mp = mps

    if not packed_nlri and not packed_mp:
        return ''

    return (msg for msg in self.make_message(msg_size, attr, MPRNLRI(packed_mp).pack(addpath), ''.join(nlri.pack(addpath) for nlri in packed_nlri)))

def _call_series(self, series):
    level = getattr(self, 'level', None)
    axis = getattr(self, 'axis', None)
    skipna = getattr(self, 'skipna', None)
    numeric_only = getattr(self, 'numeric_only', None)
    bool_only = getattr(self, 'bool_only', None)
    if axis == 'index':
        axis = 0
    self._axis = axis
    # Enable specify level if we support groupby
    if level is not None:
        raise NotImplementedError('Not support specified level now')

    empty_series = build_series(series)
    func_name = getattr(self, '_func_name')
    if func_name == 'count':
        reduced_series = empty_series.count(level=level)
    elif func_name == 'nunique':
        reduced_series = empty_series.nunique()
    elif func_name in ('all', 'any'):
        reduced_series = getattr(empty_series, func_name)(axis=axis, level=level, bool_only=bool_only)
    elif func_name == 'size':
        reduced_series = empty_series.size
    elif func_name == 'custom_reduction':
        reduced_series = getattr(self, 'custom_reduction').__call_agg__(empty_series)
    elif func_name == 'str_concat':
        reduced_series = pd.Series([empty_series.str.cat(**getattr(self, 'get_reduction_args')())])
    else:
        reduced_series = getattr(empty_series, func_name)(axis=axis, level=level, skipna=skipna,
                                                          numeric_only=numeric_only)

    return self.new_scalar([series], dtype=np.array(reduced_series).dtype)

def copy(self,source,destination,dereference=False,pattern=None):
    """
    Copies a file or a folder from 'remote' source to
    'remote' destination.
    Automatically redirects to copyfile or copytree.

    Args:
        source (str)       - path to local file
        destination (Str)  - path to remote file
        dereference (bool) - follow symbolic links
                             default = False
        pattern (str) - copies list of files matching filters
                        in Unix style. Tested on unix only.
                        default = None

    Raises:
        ValueError if 'remote' source or destination is not valid
        OSError if source does not exist
    """
    if not source:
        raise ValueError("Input source to copy "
                         "must be a non empty object")
    if not destination:
        raise ValueError("Input destination to copy "
                         "must be a non empty object")
    if not os.path.exists(os.path.join( self.curdir,source )):
        raise OSError("Source not found")

    # exotic case where destination = source
    if self.normalize(source) == self.normalize(destination):
        raise ValueError("Cannot copy from itself to itself")

    # by default, overwrite old files
    if self.isfile(destination) or self.isdir(destination):
        self.rmtree(destination)

    if pattern:
        file_list = self.listdir(source,pattern)
        to_copy = [os.path.join(source,i) for i in file_list ]
        to_copy_to = [os.path.join(destination,i) for i in file_list ]

        for this_src,this_dst in zip(to_copy,to_copy_to):
            splitted_list = self._os_path_split_asunder(this_dst)

            does_dir_exist = ''
            for this_dir in splitted_list[:-1]:
                does_dir_exist = os.path.join(does_dir_exist,this_dir)
                try:
                    self.mkdir(does_dir_exist)
                except OSError as e:
                    if 'File exists' in str(e):
                        pass

            if self.isdir(this_src):
                self.copytree(this_src,this_dst,dereference)
            else:
                self.copyfile(this_src,this_dst)

    else:
        if self.isdir(source):
            return self.copytree(source,destination,dereference)
        else:
            return self.copyfile(source,destination)

