def _get_step_view_from_execution(
    self, execution: proto.Execution
) -> StepView:
    """Get original StepView from an execution.

    Args:
        execution: proto.Execution object from mlmd store.

    Returns:
        Original `StepView` derived from the proto.Execution.
    """
    step_name = self.step_type_mapping[execution.type_id]
    # TODO [ENG-134]: why is the name like this?
    # The name is derived from the step type mapping, which may not be intuitive.
    # Consider renaming the mapping or adding documentation for clarity.
    if step_name.startswith(BASE_STEP_PREFIX):
        step_name = step_name[len(BASE_STEP_PREFIX) :]

    step_parameters = {
        k: json.loads(v.string_value)
        for k, v in execution.custom_properties.items()
    }

    return StepView(
        id_=execution.id,
        name=step_name,
        parameters=step_parameters,
        metadata_store=self,
    )

def purestr(x):
    """ A string that follows obj = type(obj)(*obj.args) exactly """
    if not isinstance(x, Basic):
        return str(x)
    return srepr(x)

def __new__(cls, class_name, bases, class_dict):
    names = []
    names_with_refs = []

    # First pre-process to handle all the Includes
    includes = {}
    removes = []
    for name, prop in class_dict.iteritems():
        if not isinstance(prop, Include):
            continue

        delegate = prop._delegate
        if not (isinstance(delegate,type) and issubclass(delegate,PropertyGroup)):
            continue

        if prop._prefix is None:
            prefix = name + "_"
        else:
            prefix = prop._prefix + "_"
        for subpropname in dir(delegate):
            if subpropname.startswith("__"):
                continue
            fullpropname = prefix + subpropname
            # Accessing the property through getattr to support subclassing
            subprop = getattr(delegate, subpropname)
            if isinstance(subprop, BaseProperty):
                # If it's an actual instance, then we need to make a copy
                # so two properties don't write to the same hidden variable
                # inside the instance.
                subprop = copy(subprop)
            includes[fullpropname] = subprop
        # Remove the name of the Include attribute itself
        removes.append(name)

    # Update the class dictionary, taking care not to overwrite values
    # from the delegates that the subclass may have explicitly defined
    for key, val in includes.iteritems():
        if key not in class_dict:
            class_dict[key] = val
    for tmp in removes:
        del class_dict[tmp]

    for name, prop in class_dict.iteritems():
        if isinstance(prop, BaseProperty):
            prop.name = name
            if hasattr(prop, 'has_ref') and prop.has_ref:
                names_with_refs.append(name)
            names.append(name)
        elif isinstance(prop, type) and issubclass(prop, BaseProperty):
            # Support the user adding a property without using parens,
            # i.e. using just the BaseProperty subclass instead of an
            # instance of the subclass
            newprop = prop.autocreate(name=name)
            class_dict[name] = newprop
            newprop.name = name
            names.append(name)
    class_dict["__properties__"] = names
    class_dict["__properties_with_refs__"] = names_with_refs
    return type.__new__(cls, class_name, bases, class_dict)

