def getRHSDeriv(self, tInd, src, v, adjoint=False):

    C = self.mesh.edgeCurl
    MeSigmaI = self.MeSigmaI

    def MeSigmaIDeriv(u):
        return self.MeSigmaIDeriv(u)

    MfMui = self.MfMui

    _, s_e = src.eval(self, self.times[tInd])
    s_mDeriv, s_eDeriv = src.evalDeriv(self, self.times[tInd],
                                       adjoint=adjoint)

    if adjoint:
        if self._makeASymmetric is True:
            v = self.MfMui * v
        if isinstance(s_e, Utils.Zero):
            MeSigmaIDerivT_v = Utils.Zero()
        else:
            MeSigmaIDerivT_v = MeSigmaIDeriv(s_e).T * C.T * v

        RHSDeriv = (MeSigmaIDerivT_v + s_eDeriv( MeSigmaI.T * (C.T * v)) +
                    s_mDeriv(v))

        return RHSDeriv

    if isinstance(s_e, Utils.Zero):
        MeSigmaIDeriv_v = Utils.Zero()
    else:
        MeSigmaIDeriv_v = MeSigmaIDeriv(s_e) * v

    temp = MeSigmaIDeriv_v + MeSigmaI * s_eDeriv(v) + s_mDeriv(v)

    # Modified to handle Zero class correctly
    if isinstance(temp, Utils.Zero):
        RHSDeriv = C * temp
    else:
        RHSDeriv = C * temp.astype(float)

    if self._makeASymmetric is True:
        return self.MfMui.T * RHSDeriv
    return RHSDeriv

def __repr__(self):
    def format_text(text):
        text = text.replace('\n', ' ').strip()
        if len(text) > 50:
            return text[:50] + '...'
        return text
    desc = format_text(self.description)
    return '<SurveyText({}, {}): "{}">'.format(self.id, self.survey_id, desc)

def sync_remote_repositories(user_id):
    user = User.objects.filter(pk=user_id).first()
    if not user:
        return

    # Removed log to avoid OOM issues

    failed_services = set()
    for service_cls in registry:
        for service in service_cls.for_user(user):
            try:
                service.sync()
            except SyncServiceError:
                failed_services.add(service.provider_name)
    if failed_services:
        msg = _(
            'Our access to your following accounts was revoked: {providers}. '
            'Please, reconnect them from your social account connections.'
        )
        raise Exception(
            msg.format(providers=', '.join(failed_services))
        )

def convex_conj(self):
    """The conjugate functional of IndicatorLpUnitBall.

    The convex conjugate functional of an ``Lp`` norm, ``p < infty`` is the
    indicator function on the unit ball defined by the corresponding dual
    norm ``q``, given by ``1/p + 1/q = 1`` and where ``q = infty`` if
    ``p = 1`` [Roc1970]_. By the Fenchel-Moreau theorem, the convex
    conjugate functional of indicator function on the unit ball in ``Lq``
    is the corresponding Lp-norm [BC2011]_.
    """
    if self.exponent == np.inf:
        return L1Norm(self.domain)
    elif self.exponent == 2:
        return L2Norm(self.domain)
    else:
        # Implementing Lp-norm functional for p < infinity
        return LpNorm(self.domain, self.exponent)

def iconName(self, background_color):
    # Check if the background color is dark
    is_dark = (background_color[0] * 0.299 + background_color[1] * 0.587 + background_color[2] * 0.114) < 186
    if is_dark:
        return '{}_white'.format(self._iconNamePrefix)
    return '{}_black'.format(self._iconNamePrefix)

def _publish(self, context: SnsPublishContext, subscriber: SnsSubscription):
    try:
        region = extract_region_from_arn(subscriber["Endpoint"])
        lambda_client = connect_to(region_name=region).awslambda.request_metadata(
            source_arn=subscriber["TopicArn"], service_principal="sns"
        )
        event = self.prepare_message(context.message, subscriber)
        inv_result = lambda_client.invoke(
            FunctionName=subscriber["Endpoint"],
            Payload=to_bytes(event),
            InvocationType=InvocationType.Event,
        )
        status_code = inv_result.get("StatusCode")
        payload = inv_result.get("Payload")
        if payload:
            delivery = {
                "statusCode": status_code,
                "providerResponse": json.dumps({"lambdaRequestId": long_uid()}),
            }
            store_delivery_log(context.message, subscriber, success=True, delivery=delivery)

    except Exception as exc:
        LOG.info(
            "Unable to run Lambda function on SNS message: %s %s", exc, traceback.format_exc()
        )
        store_delivery_log(context.message, subscriber, success=False)
        message_body = create_sns_message_body(
            message_context=context.message, subscriber=subscriber
        )
        sns_error_to_dead_letter_queue(subscriber, message_body, str(exc))

