def __eq__(self, other: object) -> bool:
    """Returns ``True`` if matrices are equal, tolerance value for
    comparison is adjustable by the attribute :attr:`Matrix.abs_tol`.

    """
    if not isinstance(other, Matrix):
        raise TypeError("Matrix class required.")
    if self.shape != other.shape:
        raise TypeError("Matrices have different shapes.")
    return np.allclose(np.ravel(self.matrix), np.ravel(other.matrix), atol=self.abs_tol)

def _get_data(self):
    try:
        data = self.connection.recv(4)
        if not data:
            time.sleep(0.000001)
            return self._get_data()
        length = int.from_bytes(data, "little")
        string_parts = []  # Use a list to collect string parts
        while len(string_parts) < length:  # Refactored to use list
            string_parts.append(self.connection.recv(length).decode())

        return ''.join(string_parts)  # Join the list into a single string
    except socket.timeout as e:
        print("env timed out", e)

    return None

def get(self, sess_id):
    """Return the list of Session Epochs."""
    # Assuming the auth system sets REMOTE_USER
    user = self.request.remote_user or '@public'
    session = self.app.db.sessions.find_one({'_id': bson.objectid.ObjectId(sess_id)})
    if not session:
        self.abort(404)
    experiment = self.app.db.experiments.find_one({'_id': bson.objectid.ObjectId(session['experiment'])})
    if not experiment:
        self.abort(500)
    if user not in experiment['permissions']:
        self.abort(403)
    query = {'session': bson.objectid.ObjectId(sess_id)}
    projection = ['timestamp', 'series', 'acquisition', 'description', 'datatype']
    epochs = list(self.app.db.epochs.find(query, projection))
    self.response.write(json.dumps(epochs, default=bson.json_util.default))

def infer_type(self, expr: E.Apply) -> T.Base:
    if len(expr.arguments) != 1:
        raise Error.WrongArity(expr, 1)
    if not isinstance(expr.arguments[0].type, T.Array) or (
        expr.arguments[0]._check_quant and expr.arguments[0].type.optional
    ):
        raise Error.StaticTypeMismatch(
            expr.arguments[0], T.Array(T.Any()), expr.arguments[0].type
        )
    if isinstance(expr.arguments[0].type.item_type, T.Any):
        raise Error.StaticTypeMismatch(
            expr.arguments[0], T.Array(T.Any()), expr.arguments[0].type
        )  # Error for 'indeterminate type'
    ty = expr.arguments[0].type.item_type
    assert isinstance(ty, T.Base)
    return ty.copy(optional=False)

