def __init__(self, queue, job_id, ops):
  """Constructor for the _QueuedJob.

  @type queue: L{JobQueue}
  @param queue: our parent queue
  @type job_id: job_id
  @param job_id: our job id
  @type ops: list
  @param ops: the list of opcodes we hold, which will be encapsulated
      in _QueuedOpCodes

  """
  if not ops:
    raise ValueError("No opcodes provided")  # Using a better exception

  self.queue = queue
  self.id = job_id
  self.ops = [_QueuedOpCode(op) for op in ops]
  self.log_serial = 0
  self.received_timestamp = TimeStampNow()
  self.start_timestamp = None
  self.end_timestamp = None

  # In-memory attributes
  self.lock_status = None

  # Condition to wait for changes
  self.change = threading.Condition(self.queue._lock)

def test_index_haystack(self):
    db = self.db
    coll = self.coll
    yield coll.drop_indexes()

    _id = yield coll.insert({
        "pos": {"long": 34.2, "lat": 33.3},
        "type": "restaurant"
    })
    yield coll.insert({
        "pos": {"long": 34.2, "lat": 37.3}, "type": "restaurant"
    })
    yield coll.insert({
        "pos": {"long": 59.1, "lat": 87.2}, "type": "office"
    })

    yield coll.create_index(filter.sort(filter.GEOHAYSTACK("pos") +
                                        filter.ASCENDING("type")), **{"bucket_size": 1})

    # Sending command directly
    command = SON([
        ("geoSearch", "mycol"),
        ("near", [33, 33]),
        ("maxDistance", 6),
        ("search", {"type": "restaurant"}),
        ("limit", 30),
    ])

    results = yield db.command(command)
    self.assertEqual(2, len(results["results"]))
    self.assertEqual({
        "_id": _id,
        "pos": {"long": 34.2, "lat": 33.3},
        "type": "restaurant"
    }, results["results"][0])

