def _sqlalchemy_type(self, col):

    dtype = self.dtype or {}
    if col.name in dtype:
        return self.dtype[col.name]

    col_type = self._get_notnull_col_dtype(col)

    from sqlalchemy.types import (BigInteger, SmallInteger, Float, Text, Boolean,
        DateTime, Date, Time)

    if col_type == 'datetime64' or col_type == 'datetime':
        try:
            tz = col.tzinfo
            return DateTime(timezone=True)
        except:
            return DateTime
    if col_type == 'timedelta64':
        warnings.warn("the 'timedelta' type is not supported, and will be "
                      "written as integer values (ns frequency) to the "
                      "database.", UserWarning)
        return BigInteger
    elif col_type == 'floating':
        return Float
    elif col_type == 'integer':
        # Refined integer size based on expected range
        return SmallInteger  # or BigInteger based on your needs
    elif col_type == 'boolean':
        return Boolean
    elif col_type == 'date':
        return Date
    elif col_type == 'time':
        return Time
    elif col_type == 'complex':
        raise ValueError('Complex datatypes not supported')

    return Text

