def _full_path(self) -> str:
    exe = self.held_object
    # Check if exe is an instance of build.Executable
    if isinstance(exe, build.Executable):
        assert self.interpreter.backend is not None
        return self.interpreter.backend.get_target_filename_abs(exe)
    # Ensure that the executable was found
    if not self.found():
        raise InterpreterException('Unable to get the path of a not-found external program')
    path = exe.get_path()
    assert path is not None
    return path

def regularization(self, lbd_w: float = 1.0, lbd_b: float = 1.0) -> tf.Tensor:
    loss = 0.0
    for l in self.ml_layer:
        loss += l.regularization(lbd_w=lbd_w, lbd_b=lbd_b)
    return loss

def condense_to_fragments(self, property, fragments, w_power=1):
    # Check if fragments are valid
    if fragments is None or not all(isinstance(frag, list) for frag in fragments):
        raise ValueError('Fragments must be a list of lists.')

    condensed = np.zeros(len(fragments))
    for index, frag in enumerate(fragments):
        weight = np.zeros(self.grid.points.shape[0])
        for item in frag:
            weight += self.part.cache.load('at_weights', item)
        share = self.grid.integrate(weight**w_power, property)
        condensed[index] = share
    return condensed

def _call(self, method, *args, **kwargs):
    tid = self._tid.next()
    msg = {
        "method": method,
        "params": list(args)
    }
    is_notify = "_notify" in kwargs
    if not is_notify:
        msg["id"] = tid
    msg = json.dumps(msg)
    for timeout in self._service.iter_rpc_retry_timeout():
        services = self._service.resolve_service(self._service_name)
        if not services:
            raise RPCError("Service not found")
        for svc in services:
            client = tornado.httpclient.AsyncHTTPClient()
            try:
                response = yield client.fetch(
                    "http://%s/api/%s/" % (svc, self._api),
                    method="POST",
                    body=msg
                )
            except tornado.httpclient.HTTPError as why:
                if why.code != 499:
                    raise RPCError("RPC Call Failed: %s", why)
                else:
                    self._service.logger.info(
                        "Service is not available at %s. Retrying",
                        svc
                    )
                    continue
            except tornado.httpclient.HTTPClientError as why:
                # @todo: Grab connection refused
                # wait for timeout
                self._service.logger.info(
                    "Connection refused when trying to reach %s. Retrying after timeout.",
                    svc
                )
                continue
            except Exception as why:
                raise RPCError("RPC Call Failed: %s" % why)
            if not is_notify:
                result = json.loads(response.body)
                if result.get("error"):
                    raise RPCError("RPC Call Failed: %s" % result["error"])
                else:
                    raise tornado.gen.Return(result["result"])
        self._service.logger.info(
            "All services are not available. Waiting %s seconds"
        )
        yield tornado.gen.sleep(timeout)

def certreport(md, t, name, args, id, expiration_threshold=864000):
    """
    Generate a report of the certificates (optionally limited by expiration time) found in the selection.
    """
    try:
        from OpenSSL import crypto
    except ImportError as ex:
        logging.error("certreport requires pyOpenSSL")
        return t

    if t is None:
        raise ValueError("Your plumbing is missing a select statement.")

    seen = {}
    for eid in t.xpath("//md:EntityDescriptor/@entityID", namespaces=NS):
        for cd in t.xpath("md:EntityDescriptor[@entityID='%s']//ds:X509Certificate" % eid, namespaces=NS):
            try:
                cert_pem = cd.text
                cert_der = base64.b64decode(cert_pem)
                m = hashlib.sha1()
                m.update(cert_der)
                fp = m.hexdigest()
                if not seen.get(fp, False):
                    seen[fp] = True
                    cert = crypto.load_certificate(crypto.FILETYPE_ASN1, cert_der)
                    et = datetime.strptime(cert.get_notAfter(), "%Y%m%d%H%M%SZ")
                    now = datetime.now()
                    dt = et - now
                    if dt.total_seconds() < 0:
                        e = cd.getparent().getparent().getparent().getparent().getparent()
                        md.annotate(e, "certificate-error", "certificate has expired", "%s expired %s ago" % (_subject(cert), -dt))
                        logging.error("%s expired %s ago" % (eid, -dt))
                    elif dt.total_seconds() < expiration_threshold:
                        e = cd.getparent().getparent().getparent().getparent().getparent()
                        print(e)
                        md.annotate(e, "certificate-warning", "certificate about to expire", "%s expires in %s" % (_subject(cert), dt))
                        logging.warn("%s expires in %s" % (eid, dt))
            except Exception as ex:
                logging.error(ex)

def set_signature(name, **kwargs):
    """
    Update a signature defined by a name.

    Variables:
    name    =>     Name of the signature

    Arguments:
    None

    Data Block (REQUIRED):
    {                         # Tagcheck signature block
     "callback": None,          # Callback function when the signature fires
     "classification": None ,   # Classification of the signature
     "comment": "",             # Comments about the signature
     "implant_family": "",      # Implant family
     "score": 'HIGH',           # Score assigned to the signature
     "status": "DEPLOYED",      # Status of the signature (DEPLOYED, DISABLED)
     "threat_actor": "",        # Threat actor assigned to the signature
     "values": [""],            # Rule regexes
    }

    Result example:
    {"success": true}      #If saving the rule was a success or not
    """
    # TODO: A user should not be able to change the signature status if it's already in a deployed state
    user = kwargs['user']
    data = request.json

    if 'name' in data and name != data['name']:
        return make_api_response({"success": False}, "You cannot change the tagcheck signature name", 400)

    if not is_valid_status(data, user):
        return make_api_response("", "Only admins are allowed to deploy or disable signatures", 403)

    if not Classification.is_accessible(user['classification'], data.get('classification',
                                                                         Classification.UNRESTRICTED)):
        return make_api_response("", "You are not allowed to add a signature with "
                                     "higher classification than yours", 403)

    sig = STORAGE.tc_signature.get(name, as_obj=False)
    if sig:
        if sig.get('status') == 'DEPLOYED' and 'status' in data:
            return make_api_response({"success": False}, "Cannot change status of a deployed signature", 400)
        sig.update(data)
        return make_api_response({"success": STORAGE.tc_signature.save(name, sig)})
    else:
        return make_api_response({"success": False}, "Signature does not exist", 404)

def numpify(xs, pad=0, keys=None, dtypes=None):
    """Converts a dict or list of Python data into a dict of numpy arrays."""
    is_dict = isinstance(xs, dict)
    xs_np = {} if is_dict else [0] * len(xs)
    xs_iter = xs.items() if is_dict else enumerate(xs)

    for i, (key, x) in enumerate(xs_iter):
        if keys is None or key in keys:
            shape = get_list_shape(x)
            if dtypes is None:
                dtype = np.int64
            else:
                dtype = dtypes[i]
            x_np = np.full(shape, pad, dtype)
            dims = len(shape)
            if dims == 0:
                x_np = x
            elif dims == 1:
                x_np[0:shape[0]] = x
            elif dims == 2:
                for j, y in enumerate(x):
                    x_np[j, 0:len(y)] = [ys for ys in y]  # this comprehension turns DynamicSubsampledList into a list
            elif dims == 3:
                for j, ys in enumerate(x):
                    for k, y in enumerate(ys):
                        x_np[j, k, 0:len(y)] = y
            else:
                # Extend to general case
                x_np = np.full(shape, pad, dtype)
                for idx in np.ndindex(shape):
                    x_np[idx] = x[idx] if idx < len(x) else pad
            xs_np[key] = x_np
        else:
            xs_np[key] = x
    return xs_np

def _make_elementwise_binary_reference(
    prim: Callable,
    *,
    type_promotion_kind,
    aten_op=infer_aten_op,
    has_out=True,
    supports_lhs_python_scalar=True,
    supports_rhs_python_scalar=True,
) -> Callable:
    @elementwise_type_promotion_wrapper(
        type_promoting_args=("a", "b"),
        type_promotion_kind=type_promotion_kind,
    )
    def _ref(
        a: Union[Tensor, NumberType],
        b: Union[Tensor, NumberType],
    ) -> Tensor:
        if not supports_lhs_python_scalar and isinstance(a, Number):
            raise ValueError(
                "Received a lhs Python scalar to an elementwise binary operation that does not accept lhs scalars!"
            )

        if not supports_rhs_python_scalar and isinstance(b, Number):
            raise ValueError(
                "Received a rhs Python scalar to an elementwise binary operation that does not accept rhs scalars!"
            )

        # Enable this for operations that support it, like add
        if isinstance(a, Number) and isinstance(b, Number):
            return prim(a, b)

        a, b = _maybe_broadcast(a, b)
        return prim(a, b)

    if has_out:
        _ref = out_wrapper()(_ref)

    if aten_op is infer_aten_op:
        aten_op = getattr(torch.ops.aten, prim.__name__.split(".")[0])
    if aten_op is not None:
        register_decomposition(aten_op)(_ref)

    return _ref

def dlogpdf_dlink_dtheta(self, f, y, Y_metadata=None):
    dlogpdf_dlink_dvar = self.dlogpdf_dlink_dvar(f, y, Y_metadata=Y_metadata)
    dlogpdf_dlink_dv = -2 * self.v * (self.v + 1) * (y - f) / ((y - f) ** 2 + self.sigma2 * self.v) ** 2  # Fixed calculation for dlogpdf_dlink_dv
    return np.array((dlogpdf_dlink_dvar, dlogpdf_dlink_dv))

