def collection_to_feedcollection_information(service, collection, version):

    polling_instances = []
    for poll in service.get_polling_services(collection):
        polling_instances.extend(poll_service_to_polling_service_instance(poll, version=version))

    push_methods = service.get_push_methods(collection)

    subscription_methods = []
    for s in service.get_subscription_services(collection):
        subscription_methods.extend(subscription_service_to_subscription_method(s, version=version))

    if collection.accept_all_content:
        supported_content = []
    else:
        supported_content = content_binding_entities_to_content_bindings(collection.supported_content, version=version)

    if version == 11:
        inbox_instances = []
        for inbox in service.get_receiving_inbox_services(collection):
            inbox_instances.extend(inbox_to_receiving_inbox_instance(inbox))

        return tm11.CollectionInformation(
            collection_name = collection.name,
            collection_description = collection.description,
            supported_contents = supported_content,
            available = collection.available,

            push_methods = push_methods,
            polling_service_instances = polling_instances,
            subscription_methods = subscription_methods,

            collection_volume = service.get_volume(collection),  # Removed explicit int conversion
            collection_type = collection.type,
            receiving_inbox_services = inbox_instances
        )
    else:

        return tm10.FeedInformation(
            feed_name = collection.name,
            feed_description = collection.description,
            supported_contents = supported_content,
            available = collection.available,

            push_methods = push_methods,
            polling_service_instances = polling_instances,
            subscription_methods = subscription_methods
            # collection_volume, collection_type, and receiving_inbox_services are not supported in TAXII 1.0
        )

def _pbiVecAccMap(self, tIdMap):
    return {'rname': (lambda x, m=tIdMap: m[x.tId]),
            'length': (lambda x: x.aEnd - x.aStart),
            'qname': (lambda x: x.qId),
            'zm': (lambda x: x.holeNumber),
            'pos': (lambda x: x.tStart),
            'readstart': (lambda x: x.aStart),
            'tstart': (lambda x: x.tStart),
            'tend': (lambda x: x.tEnd),
           }

def _create_product(self, metadata_type, product_type, data_measurements, storage, stats_metadata,
                    custom_metadata):
    product_definition = {
        'name': self.name,
        'description': 'Description for ' + self.name,
        'metadata_type': metadata_type.name,
        'metadata': {
            'product_type': product_type,
            'statistics': stats_metadata,
            **custom_metadata
        },
        'storage': storage,
        'measurements': data_measurements
    }
    Product.validate(product_definition)
    return Product(metadata_type, product_definition)

def logMsg(title, msg, level = 1):

    logLevel = xbmcaddon.Addon().getSetting('logLevel')

    if(logLevel >= level):
        if(logLevel == 1):
            try:
                xbmc.log(title + " -> " + inspect.stack()[1][3] + " : " + str(msg))
            except UnicodeEncodeError:
                xbmc.log(title + " -> " + inspect.stack()[1][3] + " : " + str(msg.encode('utf-8')))
        else:
            try:
                xbmc.log(title + " -> " + str(msg))
            except UnicodeEncodeError:
                xbmc.log(title + " -> " + str(msg.encode('utf-8')))
